class Solution {
    public: vector<int> shortestAlternatingPaths(int n,vector<vector<int>>& redEdges,vector<vector<int>>& blueEdges){
        vector<vector<vector<int>>> graph(2,vector<vector<int>>(n));
        for(auto& edge:redEdges)graph[0][edge[0]].push_back(edge[1]);
        for(auto& edge:blueEdges)graph[1][edge[0]].push_back(edge[1]);
        vector<array<int,2>> distance(n,array<int,2>{
            -1,-1
        });
        queue<pair<int,int>> pending;
        for(int color=0;color<2;++color){
            distance[0][color]=0;
            pending.push({
                0,color
            });
        }while(!pending.empty()){
            auto [node,lastColor]=pending.front();
            pending.pop();
            int nextColor=1-lastColor;
            for(int next:graph[nextColor][node])if(distance[next][nextColor]<0){
                distance[next][nextColor]=distance[node][lastColor]+1;
                pending.push({
                    next,nextColor
                });
            }
        }
        vector<int> answer(n);
        for(int i=0;i<n;++i)answer[i]=distance[i][0]<0?distance[i][1]:distance[i][1]<0?distance[i][0]:min(distance[i][0],distance[i][1]);
        return answer;
    }
};
